write('supabase/functions/scout-component-sandbox-mcp/spine_grouped_portfolio_map_renderer_test.mjs',"""import assert from'node:assert/strict';import{readFile}from'node:fs/promises';import{build}from'esbuild';import{makePortfolioPayload}from'./sandbox_portfolio_test_fixtures.mjs';const d=new URL('./',import.meta.url);async function bundle(p){const r=await build({entryPoints:[new URL(p,d).pathname],bundle:true,format:'esm',platform:'node',target:'node22',write:false});return await import(`data:text/javascript;base64,${Buffer.from(r.outputFiles[0].text).toString('base64')}`)}const cfg=await bundle('../_shared/scout_sandbox_spine_grouped_portfolio_config.ts'),model=await bundle('spine_grouped_portfolio_model.ts'),renderer=await bundle('spine_grouped_portfolio_map_renderer.ts'),manifest=await bundle('../_shared/scout_sandbox_manifest.ts');for(const type of cfg.SCOUT_SPINE_GROUPED_PORTFOLIO_TYPES){const payload=makePortfolioPayload(type),map=model.normalizeScoutSandboxSpineGroupedPortfolioMap(type,payload);assert.ok(map,`${type} normalizer`);assert.equal(new Set(map.members.map(m=>m.member_key)).size,map.member_count);const opportunity=model.buildScoutSandboxSpineGroupedPortfolioOpportunity(map);assert.ok(model.normalizeScoutSandboxSpineGroupedPortfolioOpportunity(type,opportunity));assert.equal(model.scoutSpineGroupedPortfolioIdentityMatches(map,opportunity),true);for(const size of [{width:456,height:210},{width:280,height:210}]){const frame=renderer.buildScoutSpineGroupedPortfolioRasterFrame(map,size.width,size.height,{tileUrlTemplate:'https://sandbox.invalid/map-tile/{z}/{x}/{y}.png'});assert.ok(frame.tiles.length>0&&frame.tiles.length<=manifest.SCOUT_SANDBOX_MAX_EMBEDDED_RASTER_TILES);for(const tile of frame.tiles)assert.equal(manifest.isScoutSandboxRasterTileAllowed(tile.z,tile.x,tile.y),true,`${type} tile ${tile.z}/${tile.x}/${tile.y}`);assert.equal(frame.markers.length,map.member_count)}}const sql=await readFile(new URL('../../migrations/20260916142000_add_spine_grouped_portfolio_sandbox.sql',d),'utf8');for(const phrase of [\"set search_path to 'pg_catalog'\",'resolved_buyer_organization_on_current_spine','partition by operational_target_key','k.buyer_org_count=1','grant execute on function public.scout_get_component_sandbox_grouped_portfolio_v1_internal(text) to service_role'])assert.ok(sql.includes(phrase),phrase);assert.equal(/buyer_organization_id\\s*=\\s*'[0-9a-f-]{36}'/i.test(sql),false,'migration must not pin generated buyer UUIDs');console.log(`Scout grouped Stage-2 portfolio checks passed for ${cfg.SCOUT_SPINE_GROUPED_PORTFOLIO_TYPES.length} types.`)\n""")
write('supabase/functions/scout-component-sandbox-mcp/SPINE_GROUPED_PORTFOLIO_MAP_CONTRACT.md',"""# Scout grouped spine portfolio map contract\n\n`spine_grouped_portfolio_map_v1` is the bounded Stage-2 adapter for multi-member opportunities that already share a resolved organization relationship in `scout.opportunity_search_spine`.\n\nThe adapter is point-only. Membership means current spine evidence resolved the member to the same buyer organization under the type-specific relationship semantics. It does **not** create parcels, ownership polygons, rights-of-way, track topology, service radii, access envelopes, project-control areas, guy-wire footprints, inspection perimeters, or operating boundaries.\n\nMembers are deduplicated by `operational_target_key`; the selected row is the highest-confidence, newest evidence row. The response fails closed unless there are at least two mapped members, every selected member has Point geometry, and the group resolves to exactly one buyer organization ID.\n\nBridge-agency membership does not narrow an owner-or-agency role to legal ownership. Railroad crossing points are not connected into inferred track geometry. Permit-named contractor membership does not prove prime-contract authority or field progress. FCC owner/operator records do not establish service radius, inspection need, access, or work availability.\n\nRaster rendering uses the common bounded tile allowlist and the same workerless 2D canvas/image path as the established portfolio maps.\n""")

